"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["9840"],{3582(e,t,n){n.r(t),n.d(t,{metadata:()=>o,default:()=>d,frontMatter:()=>i,contentTitle:()=>s,toc:()=>u,assets:()=>c});var o=JSON.parse('{"id":"reference/accountMigration","title":"ALMS Account Migration Overview","description":"almsc \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. Original page.","source":"@site/docs/reference/accountMigration.md","sourceDirName":"reference","slug":"/reference/accountMigration","permalink":"/personal-av-docs/docs/reference/accountMigration","draft":false,"unlisted":false,"editUrl":"https://github.com/andreyjv/personal-av/tree/docs/documentation-revamp/PRD_documentation-revamp/website/docs/reference/accountMigration.md","tags":[],"version":"current","sidebarPosition":99,"frontMatter":{"title":"ALMS Account Migration Overview","sidebar_label":"ALMS Account Migration Overview","sidebar_position":99,"edition":"almsc","source":"https://doc.airvantage.net/almsc/reference/accountMigration","format":"md"}}'),a=n(4848),r=n(8453);let i={title:"ALMS Account Migration Overview",sidebar_label:"ALMS Account Migration Overview",sidebar_position:99,edition:"almsc",source:"https://doc.airvantage.net/almsc/reference/accountMigration",format:"md"},s,c={},u=[];function l(e){let t={a:"a",p:"p",strong:"strong",...(0,r.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsxs)(t.p,{children:[":::note Edition\n",(0,a.jsx)(t.strong,{children:"almsc"})," \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. ",(0,a.jsx)(t.a,{href:"https://doc.airvantage.net/almsc/reference/accountMigration",children:"Original page"}),".\n:::"]}),"\n",(0,a.jsx)(t.p,{children:"ALMS Account Migration Overview\nGDPR FAQ\nSearching...\nMatching results\nALMS Account Migration Overview\nOverview\nStarting in late 2022, Semtech (formerly Sierra Wireless) began converting all customer ALMS accounts to the new ALMS account format. This new format:\nSupports the new XR Series AirLink routers and support for AirLink OS;\nIntroduces many new features and capabilities that customers have been requesting; and\nProvides support for the deprecation of tokens as a licensing mechanism for ALMS, as we move to a device-level subscription model.\nMany customers have already started using the new account type, as all new accounts created since January 2022 are of this format.\nIn late 2024 we are completing this process by converting our ALMS Reseller accounts to the new format.\nThis documentation provides a detailed overview of the changes between the old and new formats, and a summary of the changes that will occur when the account migration takes place.\nAs these changes can impact your ALMS account, it is critical that you review this documentation and take actions as needed to maintain any account history that may be lost during the migration process. If you have any questions or concerns, please open a support ticket with Semtech Customer Support.\nNew ALMS Accounts\nPre-Paid Offers\nDirect Billing Offers\nIntroduction to Offers\nAccount Changes Due to the Account Migrations\nLicense Management Changes\nAccount Clean Up\nAccount Migration Examples\nPartnerships\nChanges to the Primary ALMS User Interface\nChanges to the Administration ALMS User Interface\nSupport for the XR Series Routers\nConsiderations for European Customers\nALMS Reseller Accounts\nNew ALMS Accounts\nOur new ALMS accounts continue the evolution of the ALMS solution with several new capabilities:\nSupport for the XR Series Routers:\nXR Series routers with their embedded out-of-band (OOBM) features require the new ALMS accounts to operate.\nLicense Management Change:\nHistorically, we have used \u201Ctokens\u201D as the licensing system for access to ALMS. Tokens were pooled in an account and often caused confusion for customers in managing their accounts. The new ALMS accounts use standard subscriptions for each device. This simplifies account management.\nImproved Renewal Notifications:\nFor pre-paid offers, renewals are sent to Administrators of the ALMS account, the Semtech Partner of record, and the Semtech Renewals team at least 90 days before your first device is set to expire. This ensures sufficient time to manage the renewal process.\nSupport for Sierra Wireless Connectivity:\nALMS can provide a single pane of glass to support both Semtech routers and connectivity. This includes connectivity services using standard plastic SIMs as well as support for our Ready 2 Connect (R2C) routers and gateways with integrated eSIMs that can simplify your deployment processes. Support for connectivity services requires a Direct Billing account \u2013 please see\nDirect Billing Offers\nbelow.\nWithin the new ALMS accounts, you have two options to pay for your subscriptions \u2013\nPre-Paid\n(through your Sierra Wireless Partner) or Direct Billing (direct with Sierra Wireless). The majority of accounts, and the default account configuration is Pre-Paid with your Partner. All new ALMS accounts only support one type of offer.\nPre-Paid Offers\nPre-paid Offers are the standard approach and allow you to manage your business and work with your Semtech Partner as you always have. When you need to renew your AirLink Complete services for your fleet of devices, you submit a purchase order (PO) for the fleet renewal and Semtech automatically updates the service details for the fleet in the background.\nPre-Paid Offer Benefits\nNo changes to your current processes, or how you work with your Semtech Partner (PO-based).\nYou are in full control (and responsible for) the renewal process on your devices.\nSemtech manages the service on your devices and assigns the service based on the PO received from your Semtech Partner.\nSingle pane of glass for all AirLink routers and gateways.\nPre-paid Offer Limitations\nYou cannot change offers from within ALMS. All changes need to be made by Semtech Customer Support, based on a PO for the new services.\nDoes not support Semtech connectivity\nRenewal Example \u2013 Pre-paid Offers:\nYou have a fleet of 10 AirLink RV55 devices that you purchased and registered in January 2023. As your devices include the first year of service for AirLink Complete, your devices will have full access to Semtech Customer Support, access to ALMS and full warranty coverage until January 2024 at no additional cost.\nIn October 2023, you will receive a notification from ALMS that your service is due to expire in the next 90 days. You issue a PO to your Semtech Partner for three more years of AirLink Complete for your 10 devices. When Semtech receives the PO from your Partner, we will extend the AirLink Complete service until January 2027.\nIf you fail to renew, service will be suspended on your devices as of January 2023. Those devices will be suspended in ALMS, you will no longer be able to contact Semtech Customer Support for those devices, and the warranty on your devices will expire. You will still have access to your account, and any devices can be reactivated by renewing your service.\nDirect Billing Offers\nDirect Billing Offers are an option available to customers who prefer to be directly billed for services and do not need to worry about renewals. Customers have the option to provide payment information (credit card in the USA; SEPA in Europe) at account creation, or you can speak with your Semtech Sales representative to arrange for direct invoicing\n1\n. When devices are activated under a direct billing Offer, you are invoiced in advance for the next month\u2019s service. As a result, you are billed directly for all active devices, and your service is extended based on the terms of the offer (i.e., monthly, annually etc.).\nDirect Billing Offer Benefits\nServices are invoiced every month directly by Semtech based on actual active device usage.\nYou can change offers on your devices as your business needs evolve.\nSupports Semtech connectivity services.\nServices automatically renew until explicitly canceled.\nDirect Billing Limitations\nYou are billed automatically every month.\nYou must maintain and update your billing information (e.g. replace credit cards when they expire).\nYour Semtech Partner is not involved in the process and will not be able to advise you.\nOnce converted, you cannot switch back to a yearly subscription renewal (Pre-paid) billing model.\nRenewal Example \u2013 Direct Billing Offers:\nYou have a fleet of 10 AirLink RV55 devices that you purchased and registered in January 2023. As your devices include the first year of service for AirLink Complete, your devices will have full access to Sierra Wireless Customer Support, access to ALMS, and full warranty until January 2024 at no additional cost.\nAs of January 2024, your devices will move to direct billing, and you will be invoiced, and payment processed for the next month\u2019s service of AirLink Complete. Your Customer Support and warranty dates will remain active if you maintain the service (to a maximum of five years for warranty). You do not need to issue POs or remember to renew services. You can only change offers, or terminate the service after the first year.\nIntroduction to Offers\nOffers define the services that are available on an AirLink device. This includes access to ALMS, the level of Customer Support, and can also include connectivity or other services. The Offer includes a service term (typically one, three or, five years) and are often tied to specific device types. For example, the AirLink Complete (XR80) offer can only be used with AirLink XR80 devices. It will never be displayed as a valid offer for any other device type.\nWhen a new ALMS account is created, there are a minimum of four default offers in the account. These offers are tied to different devices, and include:\nAirLink Basic:\nProvides access to ALMS only. No Customer Support or warranty extension. Only available on AirLink LX, MP, and RV devices. AirLink Basic is not available for initial registration, only renewals.\nAirLink Complete:\nProvides access to ALMS, Customer Support, and hardware warranty extension (maximum five years) for as long as the subscription is renewed. Only available on AirLink LX, MP, RV, and RX devices.\nAirLink Complete (XR80):\nProvides access to ALMS, Customer Support, Out of Band Management (OOBM) connectivity, and hardware warranty extension (maximum five years) for as long as the subscription is renewed. Only available on the AirLink XR80.\nAirLink Premium:\nProvides access to ALMS, Customer Support, OOBM connectivity, Advanced Mobility Reporting (AMR), and hardware warranty extension (maximum five years) for as long as the subscription is renewed. Only available for registration on the AirLink XR90; available for upgrade on the AirLink XR80.\nDirect Billing Offers will have other\ndefault offers\nadded to the account to support Semtech connectivity services. These offers vary depending on the location (EU versus NA) of the ALMS account. In addition, we can customize offers for customers that need a unique set of features.\nAccount Changes Due to the Account Migrations\nThe account migration process will result in a series of changes that will be noticeable in your account and include some account clean-up activities and minor changes to the user experience.\nLicense Management Changes\nHistorically, we have used \u201Ctokens\u201D as the licensing system for access to ALMS. Tokens were pooled in an account and often caused confusion for customers in managing their accounts. The new ALMS accounts use standard subscriptions for each device. This will simplify your license management.\nDevices and Current State:\nYour routers and gateways may be in different states. Devices that are\nActive\nwill be moved to the appropriate Offer for that device. This will either be AirLink Basic or AirLink Complete depending on the state of the device. Any devices in\nMaintenance Mode\nwhen the account conversion takes place will be put into\nInventory\nin the converted account. You will need to submit a purchase order to activate any devices in Inventory state.\nOffer Assignment:\nWhen the account is converted, the Offer that is applied to your devices is dependent on the original state of the device. For devices registered for AirLink Complete with valid support and warranty dates, those devices are converted to AirLink Complete Offers, and the dates will remain. Instead of having a token balance for the license, the renewal date for your service will be set based on the \u201CSupport Date\u201D.\nFor devices that are not on AirLink Complete, we will assign the AirLink Basic service to those devices. When migrating your account, we will need to convert your existing tokens to subscriptions for your devices. As tokens are a pool used across devices, when the conversion takes place, we will use the token balance to calculate the number of months of service (on average) per device in the account. We will use this information to set the Subscription renewal date for each device.\nAccount Cleanup\nAs many ALMS accounts have existed for a long time, there are a lot of devices in ALMS that are no longer active. As part of the account migration, we are going to perform some account cleanup.\nOld and Inactive Devices Deleted\nDuring the account migration, old and inactive devices will be removed from your account. We will delete:\nSystems that did not communicate with ALMS in the past year.\nDevices that have been registered but have never communicated with the platform.\nSuspend Accounts\nAny accounts with no active devices will be suspended and removed from ALMS. You will be able to create a new ALMS account from the\naccount creation page\n.\nPlease\nexport\nany data from ALMS for these devices prior to the account conversion. You can use that data to re-register devices if required.\nAccount Migration Examples\nWe have provided two examples to help illustrate what will happen when the account migration occurs. These examples will illustrate both the token migration as well as the account clean-up activities.\nCustomer without AirLink Complete\nTotal Systems at Migration:\n41 \u2013 All have no Support Date; warranty expired on all devices\nToken Balance at Migration:\n261\nMigration Date:\nMarch 25, 2023\nSystems in Account Post-Migration:\nActive: 40\nInventory:0\nBefore Migration\nAfter Migration\n1 system that communicated more than 1 year ago\nDeleted from the account\n40 Systems without AirLink Complete\nAirLink Basic Offer assigned\nRenewal Date Calculation\n261 tokens/40 systems = 6.5 months of service\nRenewal Date = April 2022 + 7 months =>\nNovember 2023\nCustomer with Mixed Services\nTotal Systems at Migration:\n13\nToken Balance at Migration:\n60\nMigration Date:\nMay 2023\nSystems in Account Post-Migration:\nActive: 11\nInventory: 0\nBefore Migration\nAfter Migration\n1 System in\nMaintenance Mode\nInventory State\nAirLink Basic Offer assigned\nNote:\nTo activate this device, the customer will need to submit a PO for service on this device.\n1 System that Never Communicated\nDeleted from the account\n1 System that Communicated more than 12 Months Ago\nDeleted from the account\n2 Systems with a Support End Date on Aug 2023\nAirLink Complete Offer assigned\nRenewal Date set to August 2024\nTokens Consumed: 2 systems * 3 months = 6 tokens\n1 System with a Support End Date on January 2023\nSystems with expired support end dates are treated as systems without support end date\nAirLink Basic Offer assigned\nRenewal Date Calculation\n54 tokens (60 - 6 AirLink Complete tokens)\n54 tokens/8 systems = 6.75 months of service\nRenewal Date = Jun 2022 + 7 months =>\nJanuary 2024\n7 Systems without Support End Date\nPartnerships\nAll Partnerships between customer accounts and their Partners remain in place after the account migration. There should be no changes as a result of the migration process.\nChanges to the Primary ALMS User Interface\nWithin the main ALMS user interface, there are some changes in the new ALMS accounts. Some are changes to support new features, while others come as a result of the account migration.\nMonitor > Systems Grid Reset\n: As a result of moving to a subscription-based approach, the details about your device\u2019s support and warranty information is presented differently. As a result, we will reset the Monitor > Systems grid configuration to its default value. If you had previously created a custom layout, you would need to reset it.\nNew Default Dashboards\n: The new ALMS account supports both device management and connectivity management features. The new accounts also have a series of new Dashboards available to you. As such, your Dashboards will be reset to the default dashboards. If you need a refresher on dashboards, please review the\nDashboard documentation\n.\nChanges to the Action Buttons\n: The new ALMS account has a different layout on the Action buttons. There are a new set for Offer management. These buttons will only be active if you are on Direct Billing Offers.\nChanges to the Administration ALMS User Interface\nWithin the ALMS Administration user interface, you will see many changes to support the new ALMS accounts.\nAccount Page\n: The account page has been updated to provide better clarity on the type of account. In addition to the UID and account name, you have a clear indication if your account is set-up with pre-paid or direct billing Offers. In addition, renewal information and display anniversary date information on the account page.\nMy Token Stock\nactivity has been replaced by a new\nRenewals\nactivity that lists all renewal operations. As part of the migration, we remove all information about tokens as they are no longer relevant to your account. This includes the transaction history for token purchases and adjustments. If you need any of this information for your records, please save the PDF records out of ALMS prior to your account conversion.\nSupport for the XR Series Routers\nXR Series routers with their embedded out-of-band (OOBM) features require the new ALMS accounts to operate. As Semtech operates\nmultiple instances of ALMS\n, it is important to understand that the SKU of the AirLink XR80 or XR90 device must align with the correct instance of ALMS, or it will not be able to activate.\nThe \u201CGlobal\u201D SKU of the AirLink XR80 or XR90 can only be registered on the European (EU) instance of ALMS.\nThe \u201CNA\u201D SKU of the AirLink XR80 or XR90 can only be registered on the North American (NA) instance of ALMS.\nPlease be aware of the device that you have purchased and ensure that your ALMS account is on the correct instance before registering your XR Series routers.\nConsiderations for European Customers\nSemtech operates\nmultiple instances of ALMS\n. The North American (NA) instance has existed for longer than the European (EU) instance, and many of the accounts created for customers in Europe were originally created on the NA server. As a result, any devices in an account on the NA server will have their data reside in the United States. You can tell which server your account is resident on by examining the URL in the browser after logging into your ALMS account.\nFor example, the following indicates an EU server and thus your data would reside in Europe:\nDuring the account migration process, we leave the account on its current server. We do have the option to move an account from the NA instance to the EU instance, but this process is manual and does have some potentially negative consequences. The following lists the pros and cons of migrating:\nPros\nData Residency\n: Your data will be stored on the EU instance of ALMS and no longer located in the United States.\nCompatibility with XR Series Routers\n: XR Series routers for the EU market can only operate with an account on the EU instance. Migrating the account ensures you can use this account with that class of devices without having to create a second account.\nSemtech Connectivity\n: If you want to use Semtech connectivity, you must have an account on the EU instance. By converting your ALMS account, you can combine router and connectivity management into a single account.\nCons\nThe main downside of migrating an account from the NA instance to the EU instance is that we need to delete the old account and re-create it on the EU instance (). The has the following implications:\nLoss of Device History\n: Devices are deleted and re-registered so they will be treated as new devices in the account and your data history for those devices will be lost.\nLoss of Account System Elements\n: Your account will be created as a new account, so any of the system elements (e.g., Templates. Alert Rules, Data Sets etc.) that you may have created will need to be re-created.\nUsers Need to be Migrated\n: Users do not need to be deleted and re-created, but you will need to open a support ticket requesting that your users be re-assigned to the new account.\nIf you would like to move your account from the NA instance to the EU instance, please contact Semtech Customer Support.\nALMS Reseller Accounts\nALMS Reseller accounts are special accounts that we provide to our Partner community to ensure that our Partners always have access to an ALMS account for demonstration purposes, to manage a fleet of demo devices, and to be able to help their customers.\nAs part of the account migration program, we are making significant improvements to these accounts to provide even more capabilities for our Partners, and to make working with us easier. The new ALMS Reseller accounts will have the following features:\nFree AirLink Services for a Limited Number of Devices\nNo cost for services on all devices for authorized Partners\n20-device limit\nFull access to all features and all device types, such as:\nAMR access\nSupport for AirLink XR80/90\nLimitation\u2014no support for Semtech connectivity (i.e. SIM cards)\nMulti-Company Registration\nMaintains the ability to register devices to any ALMS account. Supports multiple customers in single bulk registration (existing feature).\nNew \u201CCustomer\u201D Page\nReplaces the \u201CSub-account\u201D page and provides a list of all partnered accounts\nProvides visibility into any account that have Partnerships, including subscription status information\nInsight into the state of partnered accounts (number of devices, renewal state, users)\nAccount Lookup\nThis new feature allows Partners to look up a Customer\u2019s ALMS account\nThe Partner can provide an email address to retrieve ALMS account name and account UID\nRequest Partnership\nThis new automated feature allows the Partner to request a partnership with any Customer\u2019s ALMS account\nThe Partner provides an account UID\nThe Customer will need to approve and assign access rights to the Partner\nCreate an ALMS Account\nThis new feature allows a Partner to create an ALMS account for a Customer\nThe Customer will need to approve and authorize the process\nIt will automatically create the primary Admin User in the account and create a partnership with the originating Partner account\nWe will be migrating all existing ALMS Reseller accounts to the new format. This is an automated process, much like the process that we went through with customer accounts. We do not expect that there will be any major changes to your account as a result. That said, there is likely to be some account cleanup that happens during this process, so please familiarize yourself with the process, as defined in this document.\nThe Customer Support team will contact each Partner before we do the account migration to ensure that it is done at a time that does not cause any issues or inconvenience.\nExisting ALMS Accounts: With the launch of the XR Series routers, we know that many Partners created new-style ALMS accounts to work with the new devices, as their ALMS Reseller accounts did not support them. During this migration, we will merge any other accounts that you might have, including users, into your new ALMS Reseller account. When contacted by Customer Support, please advise of any additional accounts that need to be merged.\nPartners Outside the USA: We know that many ALMS Reseller accounts for Partners based outside the USA were created on the North American instance of ALMS. During this migration, we will be happy to move your account to the European, Canadian or Australian instances as desired.\nSome conditions apply.\n[return]\nHow-Tos\nThis section provides you with helpful procedures for common tasks."})]})}function d(e={}){let{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(l,{...e})}):l(e)}},8453(e,t,n){n.d(t,{R:()=>i,x:()=>s});var o=n(6540);let a={},r=o.createContext(a);function i(e){let t=o.useContext(r);return o.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function s(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:i(e.components),o.createElement(r.Provider,{value:t},e.children)}}}]);